        <p class="row__links">{calendarLinksFor(e).every((link) => link.type === 'book') && <span class="card__soon">Our case file on this is in progress.</span>} {calendarLinksFor(e).map((link) => <CalendarExplainerLink link={link} />)} <a class="row__help" href="/support/">Victim &amp; Reader Resources</a> <a class="row__help" href="/support/">Report a correction</a></p>
