    .row__links a.row__explainer{display:inline-flex;align-items:center;min-height:40px;margin-right:4px;padding:8px 14px;border:1px solid rgba(78,214,190,.72);border-radius:7px;background:rgb(78 214 190);box-shadow:0 8px 24px rgba(36,166,145,.16);color:#0d1714!important;font-size:14px;font-weight:800;line-height:1.25;text-decoration:none}
