import { categoryForTag } from '../../data/content-categories.mjs';
import { breadcrumbList } from '../../utils/page-schema.mjs';
export async function getStaticPaths() {
  const posts = await getCollection('posts');
  // Nancy Guthrie coverage is excluded from related-content rails by standing order; the pages themselves stay live.
  const caseFiles = posts.filter(p => p.data.tag === 'Case Files' && !p.data.archived && !p.slug.startsWith('nancy-guthrie-'));
  return posts.map(p => {
    const idx = caseFiles.findIndex(o => o.slug === p.slug);
    let rel = [];
    if (idx >= 0) { for (let k = 1; k <= 3; k++) rel.push(caseFiles[(idx + k) % caseFiles.length]); }
    else { rel = caseFiles.slice(0, 3); }
    rel = rel.filter(r => r && r.slug !== p.slug);
    return { params: { slug: p.slug }, props: { post: p, related: rel.map(r => ({ slug: r.slug, title: r.data.title })) } };
  });
}
const { post, related = [] } = Astro.props;
const isTupacFree = post.slug === 'why-was-keffe-d-convicted-tupac-shakur';
const isTupacWithdrawal = post.slug === 'tupac-shakur-homicide-evidence-evolution';
const isTupacRepair = isTupacFree || isTupacWithdrawal;
const formatDateUtc = (date) => date.toLocaleDateString('en-US', {
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  timeZone: 'UTC',
});
// Per-page lead-magnet matching (NEP-REV-CWK-0717AF): pick the offer that matches
// who lands on THIS post. Frontmatter `capture` wins; else classify by slug.
// DNA/genealogy -> dna guide; safety/coercive-control -> safety guide; else Jury Chess.
function pickOffer(p){
  const explicit = p.data.capture;
  if (explicit === 'dna' || explicit === 'safety' || explicit === 'jury') return explicit;
  const s = p.slug;
  if (/(dna|genetic-genealog|genealog|family-tree|othram|codis|-fgg-|fgg-|forensic-genetic)/.test(s)) return 'dna';
  if (/(coercive-control|stalking|warning-signs|stay-safe|safety)/.test(s)) return 'safety';
  return 'jury';
}
const captureOffer = pickOffer(post);
const requestedOgImage = isTupacWithdrawal ? '/og/why-was-keffe-d-convicted-tupac-shakur.png' : post.data.cover ?? `/og/${post.slug}.png`;
const socialImage = postSocialImage(post.slug, requestedOgImage);
const { Content } = await post.render();
const isCase = post.data.tag === 'Case Files';
const replacementPost = isTupacWithdrawal ? (await getCollection('posts')).find(p => '/post/' + p.slug + '/' === post.data.replacementPath) : undefined;
if (isTupacWithdrawal && !replacementPost) throw new Error('Missing withdrawal replacement post');
const pageUrl = new URL(isTupacWithdrawal ? post.data.replacementPath : Astro.url.pathname, Astro.site).href;
const mk = (m) => encodeURIComponent(pageUrl + '?utm_source=' + m + '&utm_medium=social_share');
const shareT = encodeURIComponent(replacementPost?.data.title ?? post.data.title);
const articleNode = {
  "@type":"Article",
  "headline": post.data.title,
  "description": post.data.description,
  "datePublished": post.data.pubDate.toISOString().slice(0,10),
  "author":{"@id":"https://cassiancreed.com/#cassian-creed"},
  "publisher":{"@id":"https://cassiancreed.com/#org"},
  "image": new URL(socialImage, Astro.site).href,
  "mainEntityOfPage": new URL(Astro.url.pathname, Astro.site).href,
  "articleSection": post.data.tag,
"dateModified": (post.data.updatedDate ?? post.data.pubDate).toISOString().slice(0,10)
};
// Auto-derive FAQPage from an on-page "Frequently Asked Questions"/"FAQ" section.
// Mirrors only visible Q&A text (Google structured-data guideline); emits nothing if absent.
function extractFaq(body) {
  const sec = body.match(/#{2,}\s*(?:Frequently Asked Questions|FAQ|Questions [Rr]eaders [Aa]sk)\s*\n([\s\S]*?)(?=\n#{2,}\s|\n---\s*\n|$)/i);
  if (!sec) return [];
  const out = [];
  const re = /\*\*(.+?)\*\*\s*\n*([^\n*][\s\S]*?)(?=\n\s*\n|\n\*\*|$)/g;
  let m;
  while ((m = re.exec(sec[1]))) {
    out.push({ q: m[1].trim(), a: m[2].replace(/\s+/g, ' ').trim() });
  }
  return out;
}
const faq = extractFaq(post.body);
const faqNode = faq.length ? {
  "@type":"FAQPage",
  "mainEntity": faq.map(f => ({ "@type":"Question", "name": f.q, "acceptedAnswer": { "@type":"Answer", "text": f.a } }))
