const category = categoryForTag(post.data.tag);
const breadcrumbNode = breadcrumbList([
  ['Home', '/'], [category.label, '/' + category.category + '/'], [post.data.title, '/post/' + post.slug + '/'],
], '/post/' + post.slug + '/');
const jsonld = isTupacWithdrawal ? undefined : {
  "@context": "https://schema.org", "@graph": [articleNode, breadcrumbNode, ...(faqNode ? [faqNode] : [])],
};
